    project_id: str = Query(...),
    body: Dict[str, Any] = Body(default={}),
    authorization: Optional[str] = Header(default=None),
) -> Dict[str, Any]:
    """Send a test notification to verify configuration."""
    claims = get_current_user(authorization)
    project_id = v.validate_uuid(project_id, "project_id")
    await check_project_access(project_id, claims)

    try:
        settings = db.get_notification_settings(project_id)
    except Exception as e:
        logger.exception("Failed to fetch notification settings for test: %s", e)
        raise HTTPException(status_code=503, detail="Service temporarily unavailable") from e
    if not settings or not settings.get("enabled"):
        raise HTTPException(status_code=400, detail="Notifications not enabled")

    # Send test notification
    from api.notifications import send_notification

    result = send_notification(
        project_id=project_id,
        notification_type="test",
        payload={
            "message": "This is a test notification from Hikaflow",
            "timestamp": datetime.now(timezone.utc).isoformat(),
        },
        user_id=claims.get("sub"),
    )

    return {
        "success": result.get("success", False),
        "channels_notified": result.get("channels", []),
        "errors": result.get("errors", []),
    }


